    invNoProductsHint:"সামগ্ৰী যোগ কৰক অথবা সন্ধান আৰু ফিল্টাৰ সলনি কৰক।",
    invAuthError:"আপোনাৰ ছেচন শেষ হৈছে। পুনৰ ছাইন ইন কৰক।",
    invLoadError:"ইনভেণ্টৰী লোড কৰিব পৰা নগ'ল।", invNetworkError:"NEXORA ছাৰ্ভাৰৰ সৈতে সংযোগ হোৱা নাই। API ছাৰ্ভাৰ চলি আছে নে পৰীক্ষা কৰক।",
    invValidation:"শুদ্ধ নাম আৰু শূন্য বা তাতকৈ অধিক সংখ্যা দিয়ক।",
    invSaveError:"সামগ্ৰী সংৰক্ষণ কৰিব পৰা নগ'ল।", invSaved:"সামগ্ৰী সফলভাৱে যোগ কৰা হ'ল।",
    invTenantNote:"আপোনাৰ প্ৰমাণিত ব্যৱসায়িক একাউণ্টৰ পৰা ইনভেণ্টৰী লোড হয়।",
    aiDecisionEngine: "AI সিদ্ধান্ত ইঞ্জিন",
